#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[])
{
    int current_floor = 0;          // start at floor 0
    for (int i = 1; i < argc; ++i) {
        long target = strtol(argv[i], NULL, 10);
        if (target < 0 || target > 9) {
            puts("INVALID_FLOOR");
            continue;
        }
        while (current_floor != (int)target) {
            if (current_floor < (int)target) {
                printf("MOVE_UP %d->%d\n", current_floor, current_floor + 1);
                ++current_floor;
            } else {
                printf("MOVE_DOWN %d->%d\n", current_floor, current_floor - 1);
                --current_floor;
            }
        }
        printf("ARRIVE %d\n", current_floor);
        puts("DOORS_OPEN");
        puts("DOORS_CLOSE");
    }
    printf("FINAL_FLOOR=%d\n", current_floor);
    return 0;
}
